(() => {
  const base = 'https://www.meitula.org';
  const pages = [];
  const seen = {};
  const abs = (v, b) => {
    try {
      return new URL(String(v || '').replace(/&amp;/g, '&'), b || location.href || base).href;
    } catch (e) {
      return String(v || '');
    }
  };
  const pickUrl = (raw, pageUrl) => {
    const imageUrl = abs(raw, pageUrl);
    if (!/\.(jpg|jpeg|png|webp)(\?|#|$)/i.test(imageUrl)) return '';
    if (/loading\.gif|logo|qrcode|gif\.php|url\.php/i.test(imageUrl)) return '';
    return imageUrl;
  };
  const pickDoc = (doc, pageUrl) => {
    const img = doc.querySelector('.content img');
    const raw = img ? (img.getAttribute('src') || img.getAttribute('data-src') || img.getAttribute('data-original') || '') : '';
    return pickUrl(raw, pageUrl);
  };
  const pickHtml = (html, pageUrl) => {
    const text = String(html || '');
    const block = text.match(/<div[^>]+class=["'][^"']*content[^"']*["'][\s\S]*?<\/div>/i);
    const src = block ? (block[0].match(/<img[^>]+(?:src|data-src|data-original)=["']([^"']+)["']/i) || null) : null;
    return pickUrl(src ? src[1] : '', pageUrl);
  };
  const push = (imageUrl, pageUrl) => {
    if (!imageUrl || seen[imageUrl]) return;
    seen[imageUrl] = true;
    pages.push({ index: pages.length, page: pages.length, url: imageUrl, imageUrl, pageUrl });
  };
  const href = location.href;
  const m = href.match(/\/photo\/(\d+)(?:_(\d+))?\.html/i);
  if (!m) return '[]';
  const photoId = m[1];
  const currentPage = parseInt(m[2] || '1', 10) || 1;
  const range = (location.hash.match(/mxrange=(\d+)-(\d+)/i) || []);
  const start = Math.max(1, parseInt(range[1] || String(currentPage), 10) || currentPage);
  const end = Math.min(Math.max(start, parseInt(range[2] || String(start + 9), 10) || (start + 9)), start + 9);
  for (let pageNo = start; pageNo <= end; pageNo++) {
    const pageUrl = pageNo <= 1 ? (base + '/photo/' + photoId + '.html') : (base + '/photo/' + photoId + '_' + pageNo + '.html');
    if (pageNo === currentPage) {
      push(pickDoc(document, pageUrl), pageUrl);
      continue;
    }
    try {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', pageUrl, false);
      xhr.setRequestHeader('Accept', 'text/html,application/xhtml+xml');
      xhr.setRequestHeader('Referer', base + '/');
      xhr.send(null);
      if (xhr.status >= 200 && xhr.status < 400) push(pickHtml(xhr.responseText || '', pageUrl), pageUrl);
    } catch (e) {}
  }
  return JSON.stringify(pages);
})();
